 const p=d.input,cultures=d.tests.filter(t=>t.latest?.code==='culture').map(t=>({testId:t.id,...t.latest})),active=cultures.filter(r=>r.status!=='cancelled');
 const reports=active.map(r=>{const organism=identified(r.organism)?r.organism.trim():null,conflict=!!organism&&/negative|no growth/i.test(String(r.value||'')),ast=Object.entries(r.ast||{}).map(([agent,interpretation])=>({agent,interpretation}));return {...r,organism,conflict,astRows:ast,hasAST:ast.some(x=>['S','I','R'].includes(x.interpretation)),positive:!!organism&&!conflict,final:['final','corrected'].includes(r.status),susceptible:ast.filter(x=>x.interpretation==='S'),resistant:ast.filter(x=>x.interpretation==='R'),intermediate:ast.filter(x=>x.interpretation==='I')};});
 const positive=reports.filter(r=>r.positive),ready=positive.filter(r=>r.final&&r.susceptible.length),complete=positive.length>0&&positive.every(r=>r.final&&r.susceptible.length)&&!reports.some(r=>r.conflict);
