 const constraints=[];if(!stable)constraints.push('Instability or an incomplete current stability screen: urgent clinician reassessment, not an automatic narrowing pathway.');if(!verified)constraints.push('Verify current renal, allergy and medication-safety information before selecting a revised dose.');if(!complete)constraints.push('A complete current final/corrected positive culture with susceptible options is not available for every identified isolate.');
 if(p.resistance!=='None')constraints.push('Resistance history or unknown resistance context: ID / microbiology review is needed before a narrower strategy.');
